import {FREQUENCIES,localDate,monthlyCents,calculate,emptyState,demoState,validateState,parseCSV} from './model.js';

const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',income:'M12 3v12m-4-4 4 4 4-4 M4 15v5h16v-5',wallet:'M3 6h16v14H3z M3 6V4h13v2 M15 11h6v5h-6z M17.5 13.5h.1',chart:'M5 20V10m7 10V4m7 16v-7 M3 20h19',sprout:'M12 21V11 M12 14C3 14 3 8 3 5c6 0 9 3 9 9 M12 10c0-6 3-8 9-8 0 6-3 9-9 8',activity:'M3 12h4l3-8 4 16 3-8h4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',help:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20 M9 8a3 3 0 0 1 6 0c0 2-3 2-3 5 M12 17h.01',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',calendar:'M5 5h14v16H5z M8 3v4m8-4v4M5 10h14',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6z M8 12l3 3 5-6',home:'m3 11 9-8 9 8 M5 10v11h14V10 M9 21v-7h6v7',bag:'M5 7h14l2 14H3z M9 8V6a3 3 0 0 1 6 0v2',coffee:'M4 8h12v8a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4z M16 9h2a3 3 0 0 1 0 6h-2 M7 3v2m5-2v2',plane:'m2 12 8-2V4l2-2 2 2v6l8 2v3l-8-1v5l3 2H7l3-2v-5l-8 1z',laptop:'M5 4h14v12H5z M2 20l3-4h14l3 4z',edit:'m4 16 12-12 4 4L8 20H4z M14 6l4 4',trash:'M4 6h16 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7m4-7v7',close:'m6 6 12 12 M18 6 6 18',upload:'M12 16V3m-4 4 4-4 4 4 M4 15v6h16v-6',download:'M12 3v13m-4-4 4 4 4-4 M4 17v4h16v-4',check:'m5 12 4 4L19 6',info:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20 M12 11v6m0-10h.01',target:'M12 21a9 9 0 1 0 0-18 9 9 0 0 0 0 18 M12 16a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M12 12h.01',card:'M3 5h18v14H3z M3 10h18 M6 15h4',file:'M5 2h9l5 5v15H5z M14 2v6h5 M8 12h8m-8 4h6',lock:'M6 10h12v11H6z M8 10V6a4 4 0 0 1 8 0v4'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.wallet}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s);
const uid=()=>crypto.randomUUID();
const STORAGE='penny.budget.v1';
let storageWarning=''; let state;
try{const raw=localStorage.getItem(STORAGE);if(raw){const parsed=JSON.parse(raw);if(!validateState(parsed))throw new Error();state=parsed;}else state=demoState();}catch{state=demoState();storageWarning='Your saved data could not be read. The example below has not replaced it. You can restore a backup in Preferences.';}
let page=['overview','income','budget','grow','activity'].includes(location.hash.slice(1))?location.hash.slice(1):'overview';
let model=calculate(state),importRows=[],toastTimer;
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:state.settings.currency,maximumFractionDigits:n%100===0?0:2,minimumFractionDigits:n%100===0?0:2}).format(n/100);
const amount=n=>money(Math.round(n*100));
const monthName=()=>new Date().toLocaleDateString('en-US',{month:'long',year:'numeric'});
const shortDate=d=>new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'});
const pct=(n,total)=>total?Math.round(n/total*100):0;
const button=(label,action,style='',ico='plus',attrs='')=>`<button class="btn ${style}" data-action="${action}" ${attrs}>${icon(ico)}${label}</button>`;
const empty=(title,description,action,label,ico='wallet')=>`<div class="empty">${icon(ico)}<strong>${title}</strong>${description}${action?`<br>${button(label,action,'soft')}`:''}</div>`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(state));storageWarning='';return true;}catch{storageWarning='Changes are in memory only because browser storage is unavailable. Export a backup from Preferences before leaving.';return false;}}
function save(message='Your plan is updated.'){const persisted=persist();render();toast(persisted?message:'Could not save on this device. Export a backup in Preferences.');}
function closeModal(){$('#modal').close();}
function openModal(title,content){$('#modal-content').innerHTML=`<div class="modal-heading"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${content}</div>`;$('#modal').showModal();}
const field=(label,name,value='',type='text',extra='')=>`<div class="form-field"><label for="field-${name}">${label}</label><input id="field-${name}" name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?`${extra.includes('min=')?'':'min="0"'} max="1000000000" step="0.01"`:type==='text'?'maxlength="100"':''} ${extra}></div>`;
const select=(label,name,options,value)=>`<div class="form-field"><label for="field-${name}">${label}</label><select name="${name}" id="field-${name}">${Object.entries(options).map(([key,label])=>`<option value="${esc(key)}" ${key===String(value)?'selected':''}>${label}</option>`).join('')}</select></div>`;
const formFooter=(label='Save changes')=>`<div class="form-error" role="alert" id="form-error"></div><div class="modal-actions"><button type="button" class="btn" data-action="close">Cancel</button><button type="submit" class="btn primary">${label}${icon('arrow')}</button></div>`;
function formError(message){$('#form-error').textContent=message;}
function header(title,subtitle,action='add-income',label='Add income',ico='plus'){return `<div class="page-heading"><div><div class="eyebrow">A little clarity. A lot more possibility.</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="heading-actions"><span class="btn month-button">${icon('calendar')}${monthName()}</span>${button(label,action,'primary',ico)}</div></div>`;}
function banner(){return `${storageWarning?`<div class="notice error">${esc(storageWarning)}</div>`:''}${state.demo?`<div class="demo-banner"><span><strong>A peek at what’s possible.</strong> You’re exploring with example numbers.</span><button class="text-btn" data-action="start">Use my own numbers ↗</button></div>`:''}${model.income&&!state.bills.length?`<div class="notice"><strong>Your plan still needs your essentials.</strong> Add bills and living costs before using the spending estimate. <button class="text-btn" data-action="add-bill">Add essentials ↗</button></div>`:''}${model.shortfall?`<div class="notice error"><strong>Essentials are ${money(model.shortfall)} above your monthly income.</strong> Your spending and future allocations are paused. Review your costs or add missing income.</div>`:''}${model.overspent?`<div class="notice error"><strong>You’re ${money(model.overspent)} over your spending plan.</strong> Review your activity and budget before spending more.</div>`:''}`;}
function summaryCard(label,value,sub,ico,color){return `<div class="summary-card"><div class="category-icon ${color}">${icon(ico)}</div><div class="summary-content"><small>${label}</small><div class="summary-value">${money(value)}</div></div><span class="summary-meta">${sub}</span></div>`;}
function splitCard(){const total=Math.max(model.income,model.essentials);const first=pct(model.essentials,total),second=first+pct(model.spending,total);return `<section class="card split-card"><div class="card-header"><div><h2>A place for every penny</h2><p>Your monthly income, with a little intention.</p></div><button class="text-btn" data-action="navigate" data-page="budget">Edit plan ↗</button></div><div class="split-chart"><div class="donut" role="img" aria-label="Essentials ${money(model.essentials)}, spending ${money(model.spending)}, future ${money(model.future)}" style="background:conic-gradient(#b4a0df 0% ${first}%,#ebcf9e ${first}% ${second}%,#a4c9b3 ${second}% 100%)"><div class="donut-center"><strong>${money(model.income)}</strong><small>monthly income</small></div></div><div class="legend">${[['Essentials',model.essentials,'lavender','Your everyday foundations'],['Spending',model.spending,'sand','A little room to enjoy life'],['Future you',model.future,'sage','For what comes next']].map(([label,value,color,desc])=>`<div class="legend-row"><span class="legend-dot ${color}"></span><span>${label}</span><strong>${money(value)}</strong><small>${desc} · ${pct(value,model.income)}%</small></div>`).join('')}</div></div><div class="card-footnote">${icon('info')}A flexible plan. Adjust it as life changes.</div></section>`;}
function nextStep(){let title,description,value=model.future;
if(!model.income){title='Your next chapter starts here.';description='Add your take-home income and essentials to discover what you can put toward your future.';}
else if(model.shortfall){title='Make some breathing room.';description='Your essential costs are above your income. Start by reviewing costs and any missing income.';}
else if(model.allocation.emergency){title='Give yourself a little breathing room.';description=`Set aside ${money(model.allocation.emergency)} this month toward a cushion for life’s surprises.`;value=model.allocation.emergency;}
else if(model.allocation.debt){title='Give expensive debt less of your future.';description='Consider directing this amount to high-interest debt, on top of the minimums in your essentials.';value=model.allocation.debt;}
else if(model.allocation.goals){title='Bring your next goal a little closer.';description='Your cushion is covered. Put this month’s future money toward the things you’re saving for.';value=model.allocation.goals;}
else {title='Let future you grow.';description='Explore diversified, low-cost investments for longer-term goals. Returns vary and you can lose money.';value=model.allocation.invest;}
return `<section class="card next-step"><div class="next-header"><span class="eyebrow">A thoughtful next step</span><span class="plant-icon">${icon('sprout')}</span></div><h2>${title}</h2><p>${description}</p><strong class="next-value">${money(value)} <small>/ month to put to work</small></strong><button class="btn" data-action="navigate" data-page="grow">Explore your money plan ${icon('arrow')}</button></section>`;}
function goalsOverview(){return `<section class="card goals-overview"><div class="card-header"><div><h2>Good things ahead</h2><p>Little by little, you’re getting there.</p></div><button class="text-btn" data-action="navigate" data-page="grow">All goals ↗</button></div>${state.goals.length?state.goals.slice(0,2).map((g,i)=>`<div class="goal-row"><div class="goal-top"><span class="category-icon ${i?'purple':'peach'}">${icon(i?'laptop':'plane')}</span><strong>${esc(g.name)}</strong><small>${pct(g.saved,g.target)}%</small></div><div class="progress" role="progressbar" aria-label="${esc(g.name)}" aria-valuenow="${Math.min(100,pct(g.saved,g.target))}" aria-valuemin="0" aria-valuemax="100"><span style="width:${Math.min(100,pct(g.saved,g.target))}%;${i?'background:#c3b5dd':''}"></span></div><div class="goal-bottom"><b>${amount(g.saved)} saved</b><span>of ${amount(g.target)}</span></div></div>`).join(''):empty('Something to look forward to','Start saving for something that matters to you.','add-goal','Create a goal','target')}</section>`;}
const transactionIcon=t=>t.category==='Food & drinks'?'coffee':t.category==='Shopping'?'bag':t.category==='Travel'?'plane':'card';
function activityRows(rows,editable=false){return `<div class="activity-list">${[...rows].sort((a,b)=>b.date.localeCompare(a.date)).map((t,i)=>`<div class="activity-row"><span class="category-icon ${['peach','purple','mint','blue'][i%4]}">${icon(transactionIcon(t))}</span><div class="activity-info"><strong>${esc(t.name)}</strong><small>${esc(t.category)} · ${shortDate(t.date)}</small></div><b>−${amount(t.amount)}</b>${editable?`<button class="icon-button" data-action="delete" data-kind="transactions" data-id="${esc(t.id)}" aria-label="Delete ${esc(t.name)}">${icon('trash')}</button>`:''}</div>`).join('')}</div>`;}
function overview(){return `${header('Your money, a little clearer.','A simple plan for today. A little more freedom for tomorrow.')} ${banner()}<div class="overview-grid"><section class="spend-card"><span class="card-kicker">${icon('wallet')}Yours to spend</span><span class="month-pill">Monthly estimate</span><div class="spend-amount">${money(model.remaining)}</div><p class="spend-description">After essentials, future savings, and logged spending.</p><div class="spend-footer"><span class="daily-chip">${icon('calendar')}<strong>${money(model.daily)}</strong> / day</span><span>for the next ${model.daysLeft} days</span></div><div class="spend-illustration" aria-hidden="true"><span class="tiny-star">✧</span><span class="coin">$</span><div class="wallet"></div><span class="tiny-star">✦</span></div></section><div class="summary-stack">${summaryCard('Monthly income',model.income,`${state.incomes.length} income sources`,'income','mint')}${summaryCard('Essentials covered',model.essentials,'Your monthly costs','home','peach')}${summaryCard('For future you',model.future,`${state.settings.futurePercent}% target`,'sprout','purple')}</div>${splitCard()}${nextStep()}${goalsOverview()}<section class="card activity-card"><div class="card-header"><div><h2>The little things add up</h2><p>Your recent everyday spending.</p></div><button class="text-btn" data-action="navigate" data-page="activity">View activity ↗</button></div>${model.transactions.length?activityRows(model.transactions.slice(-3)):empty('A fresh start','Log everyday purchases to keep your spending estimate current.','add-expense','Log spending','activity')}</section></div>`;}
function incomePage(){return `${header('Every income. One clear picture.','Add the money you take home, after tax and deductions.')} ${banner()}<div class="full-grid"><section class="card"><div class="card-header"><div><h2>Your income sources</h2><p>A salary, a side project, or a little extra.</p></div><span class="tag">${state.incomes.length} sources</span></div>${state.incomes.length?`<div class="table-wrap"><table><thead><tr><th>Source</th><th>Take-home pay</th><th>Frequency</th><th>Manage</th></tr></thead><tbody>${state.incomes.map(i=>`<tr><td>${esc(i.name)}</td><td>${amount(i.amount)}</td><td><span class="tag">${FREQUENCIES[i.frequency]}</span>${i.frequency==='once'?`<div class="explanation">${shortDate(i.date)}</div>`:''}</td><td><div class="table-actions"><button class="icon-button" data-action="edit-income" data-id="${esc(i.id)}" aria-label="Edit ${esc(i.name)}">${icon('edit')}</button><button class="icon-button" data-action="delete" data-kind="incomes" data-id="${esc(i.id)}" aria-label="Delete ${esc(i.name)}">${icon('trash')}</button></div></td></tr>`).join('')}</tbody></table></div><div class="mini-total"><span>Estimated monthly income</span><strong>${money(model.income)}</strong></div>`:empty('Give your plan a starting point','Add your first source of take-home income.','add-income','Add income','income')}<p class="explanation">Weekly pay × 52 ÷ 12. Every 2 weeks × 26 ÷ 12. Twice a month × 2. One-time income counts only in its dated month. These are planning averages; actual paydays can differ.</p></section><aside><div class="card"><div class="category-icon purple">${icon('upload')}</div><h2 style="margin-top:16px">Bring your income with you</h2><p class="explanation">Upload a CSV with your income sources, review the numbers, and add them to your plan.</p><div style="margin-top:18px">${button('Upload income CSV','upload','soft','upload')}</div><p class="explanation">Processed on your device. Supports CSV files; enter payslip amounts manually.</p><button class="text-btn" data-action="sample" style="margin-top:12px">Download an example CSV ↗</button></div><div class="callout" style="margin-top:20px">${icon('info')}<h3>Start with what actually arrives.</h3><p>Use your take-home pay. For variable income, choose an amount you can reliably expect and update it as your work changes.</p></div></aside></div>`;}
function budgetPage(){return `${header('A plan that fits your life.','Cover the important things. Make room for the good things.','add-bill','Add essential')} ${banner()}<div class="full-grid"><section class="card"><div class="card-header"><div><h2>Your monthly essentials</h2><p>Include bills, groceries, transport, and debt minimums.</p></div><span class="tag">${money(model.essentials)}</span></div>${state.bills.length?state.bills.map(b=>`<div class="budget-row"><span class="category-icon ${b.category==='Home'?'purple':'peach'}">${icon(b.category==='Home'?'home':b.category==='Food'?'bag':'card')}</span><span class="item-info"><strong>${esc(b.name)}</strong><small>${esc(b.category)}</small></span><b>${amount(b.amount)}</b><button class="icon-button" data-action="edit-bill" data-id="${esc(b.id)}" aria-label="Edit ${esc(b.name)}">${icon('edit')}</button><button class="icon-button" data-action="delete" data-kind="bills" data-id="${esc(b.id)}" aria-label="Delete ${esc(b.name)}">${icon('trash')}</button></div>`).join(''):empty('Keep your foundations covered','Add your monthly bills and essential living costs.','add-bill','Add an essential','home')}<p class="explanation">These amounts reserve your essentials for the month. Log only extra, discretionary purchases in Activity to avoid counting essentials twice.</p></section><aside class="card"><h2>Find your balance</h2><p class="explanation">Choose how much of your income to reserve for future you. Essentials always come first.</p><div class="range-row"><label for="future-range">Future savings target</label><strong id="future-display">${state.settings.futurePercent}%</strong></div><input type="range" id="future-range" min="0" max="80" step="1" value="${state.settings.futurePercent}" aria-describedby="range-help"><p class="explanation" id="range-help">A starting point, not a rule. Your allocation is capped at what remains after essentials.</p><div class="allocation-bar" aria-hidden="true"><span style="width:${pct(model.essentials,Math.max(model.essentials,model.income))}%"></span><span style="width:${pct(model.spending,Math.max(model.essentials,model.income))}%"></span><span style="width:${pct(model.future,Math.max(model.essentials,model.income))}%"></span></div><div class="stat-lines"><div class="stat-line"><span>Monthly income</span><b>${money(model.income)}</b></div><div class="stat-line"><span>Essentials</span><b>−${money(model.essentials)}</b></div><div class="stat-line"><span>Future you</span><b>−${money(model.future)}</b></div><div class="stat-line total"><span>Everyday spending plan</span><b>${money(model.spending)}</b></div><div class="stat-line"><span>Logged this month</span><b>−${money(model.spent)}</b></div><div class="stat-line total"><span>Left to spend</span><b>${money(model.remaining)}</b></div></div></aside></div>`;}
function growPage(){const a=model.allocation;return `${header('Make room for future you.','Small, intentional steps toward a more secure tomorrow.','financial-profile','Update your situation','settings')} ${banner()}<section class="grow-intro"><div class="category-icon">${icon('sprout')}</div><div><h2>${money(model.future)} with a little more purpose.</h2><p>Your suggested monthly allocation, based on your budget and the balances you enter.</p></div>${button('How this works','plan-help','','help')}</section><div class="steps">${[
['1','A cushion for the unexpected',a.emergency,`${amount(state.settings.emergencySaved)} saved toward your ${money(model.emergencyTarget)} target (${state.settings.emergencyMonths} months of essentials). Keep emergency money accessible, such as in an eligible insured savings account.`,'https://www.consumerfinance.gov/an-essential-guide-to-building-an-emergency-fund/','Learn about emergency funds'],
['2','Less expensive debt. More freedom.',a.debt,`${amount(state.settings.highInterestDebt)} in high-interest balances entered. After a starter cushion, consider extra debt payments before investing. Include required minimum payments in your essentials.`,'https://www.investor.gov/introduction-investing/investing-basics/save-and-invest/pay-credit-cards-or-other-high-interest','Why high-interest debt comes first'],
['3','Something worth saving for',a.goals,'After your full cushion and high-interest debt, put money toward your goals. For money you need soon, consider accessible savings and compare fees, withdrawal rules, and current interest rates.','#goals','View your savings goals'],
['4','A longer view of your money',a.invest,'For money you can leave invested for years, learn about diversified, low-cost funds and retirement accounts. Consider your time horizon, risk tolerance, and any employer match. Returns are not guaranteed; investments can lose value.','https://www.investor.gov/introduction-investing/getting-started/asset-allocation','Understand investment risk']
].map(([n,title,value,description,url,label])=>`<section class="card step-card"><div class="step-label"><span class="step-number">${n}</span><span class="tag">${value?'In your current plan':'A step to explore'}</span></div><h3>${title}</h3><p>${description}</p><div class="step-money">${money(value)} <small>/ month suggested</small></div><a class="source-link" href="${url}" ${url.startsWith('http')?'target="_blank" rel="noopener noreferrer"':'data-action="scroll-goals"'}>${label} ↗</a></section>`).join('')}</div><p class="fine-print">This is an educational starting plan, not personalized investment advice. Allocations are suggestions, not transfers or earnings. Review your full situation, taxes, employer benefits, and local account rules. Your goal balances and cushion update only when you change them.</p><div class="section-title" id="goals"><div><h2>Good things ahead</h2><p class="subtitle">Give your savings something to look forward to.</p></div>${button('New goal','add-goal','','plus')}</div><div class="goals-grid">${state.goals.length?state.goals.map(g=>`<section class="card goal-card"><div class="card-header"><div class="category-icon purple">${icon('target')}</div><button class="icon-button" data-action="delete" data-kind="goals" data-id="${esc(g.id)}" aria-label="Delete ${esc(g.name)}">${icon('trash')}</button></div><h3>${esc(g.name)}</h3><div class="goal-number">${amount(g.saved)} <small>of ${amount(g.target)}</small></div><div class="progress" role="progressbar" aria-label="${esc(g.name)}" aria-valuenow="${Math.min(100,pct(g.saved,g.target))}" aria-valuemin="0" aria-valuemax="100"><span style="width:${Math.min(100,pct(g.saved,g.target))}%"></span></div><p class="explanation">${g.saved>=g.target?'You reached your goal. Take a moment to enjoy that.':`${amount(g.target-g.saved)} to go. Every little bit counts.`}</p><div class="goal-actions">${button('Update progress','edit-goal','soft','edit',`data-id="${esc(g.id)}"`)}</div></section>`).join(''):`<section class="card">${empty('Your next good thing','A trip, a laptop, or something just for you.','add-goal','Create a savings goal','target')}</section>`}</div>`;}
function activityPage(){return `${header('The everyday picture.','Track extra purchases and keep your spending plan in sync.','add-expense','Log spending')} ${banner()}<div class="full-grid"><section class="card"><div class="card-header"><div><h2>Everyday spending</h2><p>${monthName()} · discretionary purchases only</p></div><span class="tag">${money(model.spent)} spent</span></div><div class="filters"><input id="activity-search" type="search" placeholder="Find a purchase…" aria-label="Search purchases"><select id="activity-category" aria-label="Filter spending category"><option value="">All categories</option>${['Food & drinks','Shopping','Entertainment','Travel','Other'].map(s=>`<option>${s}</option>`).join('')}</select></div><div id="activity-results">${model.transactions.length?activityRows(model.transactions,true):empty('A little awareness goes a long way','Log your first extra purchase. Essentials are already reserved in your budget.','add-expense','Log spending','activity')}</div></section><aside><div class="callout"><h3>Room left in your plan</h3><div class="spend-amount" style="font-size:36px">${money(model.remaining)}</div><p>About ${money(model.daily)} a day for the rest of this month, based on your current plan.</p></div><div class="card"><h3>A note on your numbers</h3><p class="explanation">Activity is for purchases outside your essential budget. Your rent, groceries, and other essentials are already reserved. Penny doesn’t connect to your bank or move money.</p>${button('Review my budget','navigate','soft','arrow','data-page="budget"')}</div></aside></div>`;}
function render(){model=calculate(state);const pages={overview:['Overview','grid',overview],income:['Income','income',incomePage],budget:['My budget','wallet',budgetPage],grow:['Grow & goals','sprout',growPage],activity:['Activity','activity',activityPage]};$('#navigation').innerHTML=Object.entries(pages).map(([key,[label,ico]])=>`<a class="nav-link ${page===key?'active':''}" href="#${key}" ${page===key?'aria-current="page"':''}>${icon(ico)}<span>${label}</span></a>`).join('');$('#page-label').textContent=pages[page][0];$('#main').innerHTML=pages[page][2]();document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
function navigate(next){if(next===page){render();return;}location.hash=next;}
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(['overview','income','budget','grow','activity'].includes(next)){page=next;render();window.scrollTo(0,0);}});
function incomeForm(id){const item=state.incomes.find(i=>i.id===id);openModal(item?'Edit income':'Add a little clarity',`<p>Enter the amount you receive after taxes and deductions.</p><form data-form="income" data-id="${esc(item?.id||'')}">${field('Income source','name',item?.name||'','text','placeholder="e.g. My salary" required')}${field(`Take-home amount (${state.settings.currency})`,'amount',item?.amount??'','number','placeholder="0.00" required min="0.01"')}<div class="form-grid">${select('How often?', 'frequency',FREQUENCIES,item?.frequency||'monthly')}${field('Date (for one-time income)','date',item?.date||localDate(),'date','required')}</div><p class="explanation">Only add income you can reasonably expect. Recurring amounts are converted into a monthly planning average.</p>${formFooter(item?'Save income':'Add income')}</form>`);}
function billForm(id){const item=state.bills.find(i=>i.id===id);openModal(item?'Edit an essential':'Cover an essential',`<p>Reserve the monthly amount for this bill or living cost.</p><form data-form="bill" data-id="${esc(item?.id||'')}">${field('What is it for?','name',item?.name||'','text','placeholder="e.g. Rent, groceries, credit card minimum" required')}${field(`Monthly amount (${state.settings.currency})`,'amount',item?.amount??'','number','placeholder="0.00" required min="0.01"')}${select('Category','category',{Home:'Home',Food:'Food',Bills:'Bills',Transport:'Transport',Health:'Health',Debt:'Debt minimums',Other:'Other'},item?.category||'Home')}${formFooter(item?'Save essential':'Add essential')}</form>`);}
function expenseForm(){openModal('The little things add up',`<p>Log a purchase outside your reserved essentials. It will reduce the amount left in your spending plan.</p><form data-form="expense">${field('What did you spend on?','name','','text','placeholder="e.g. Coffee with a friend" required')}${field(`Amount (${state.settings.currency})`,'amount','','number','placeholder="0.00" required min="0.01"')}<div class="form-grid">${select('Category','category',{'Food & drinks':'Food & drinks',Shopping:'Shopping',Entertainment:'Entertainment',Travel:'Travel',Other:'Other'},'Food & drinks')}${field('When?','date',localDate(),'date',`min="${model.month}-01" max="${localDate()}" required`)}</div>${formFooter('Log spending')}</form>`);}
function goalForm(id){const item=state.goals.find(i=>i.id===id);openModal(item?'A little closer to your goal':'Something to look forward to',`<p>Track money you’ve already put aside. Updating a balance does not move money or log spending.</p><form data-form="goal" data-id="${esc(item?.id||'')}">${field('Your goal','name',item?.name||'','text','placeholder="e.g. A well-earned getaway" required')}<div class="form-grid">${field('Target amount','target',item?.target??'','number','required min="0.01"')}${field('Already saved','saved',item?.saved??0,'number','required')}</div>${formFooter(item?'Update goal':'Create goal')}</form>`);}
function profileForm(){openModal('Meet yourself where you are',`<p>These details shape your suggested savings and debt plan. Keep goal savings separate from your emergency cushion.</p><form data-form="profile">${field(`Emergency savings today (${state.settings.currency})`,'emergencySaved',state.settings.emergencySaved,'number','required')}${select('Emergency cushion target','emergencyMonths',{'1':'1 month of essentials','3':'3 months of essentials','6':'6 months of essentials','12':'12 months of essentials'},state.settings.emergencyMonths)}${field(`High-interest debt balance (${state.settings.currency})`,'highInterestDebt',state.settings.highInterestDebt,'number','required')}<p class="explanation">Include expensive debt such as credit cards. Put the minimum required payments in your essential budget. Extra repayments will be suggested here.</p>${formFooter('Update my plan')}</form>`);}
function help(){openModal('A little clarity about Penny',`<p>Your plan is a monthly estimate, based on the numbers you enter.</p><ol class="help-list"><li><strong>Start with take-home income.</strong> Penny converts recurring pay into an average month. The timing of paydays may differ.</li><li><strong>Cover your essentials.</strong> Add all monthly bills, groceries, transport, and minimum debt payments.</li><li><strong>Make room for future you.</strong> Choose a percentage to reserve. It’s capped at what remains after essentials.</li><li><strong>Keep everyday spending current.</strong> Log purchases outside essentials. Your remaining budget is divided by the days left in the month, including today.</li></ol><p class="explanation">“Yours to spend” is not a bank balance or a cash-flow forecast. Check that money has arrived and upcoming payments are covered. Suggested savings are not automatically moved.</p><div class="settings-divider"></div><p class="explanation">Your budget is saved in this browser on this device. It is not synced between devices. Income CSVs are processed locally. Use Preferences to export a backup.</p><div class="modal-actions">${button('Preferences','settings','','settings')}${button('Got it','close','primary','check')}</div>`);}
function planHelp(){openModal('A practical starting plan',`<p>Here’s how Penny divides the amount you reserve for future you.</p><ol class="help-list"><li>Build a starter cushion: the smaller of ${amount(1000)} or your full emergency target. This is an adjustable planning heuristic, not a universal rule.</li><li>Direct the remaining allocation toward the high-interest debt balance you entered.</li><li>Then fill the rest of your emergency target, based on your chosen months of essentials.</li><li>Put what’s left toward incomplete savings goals, then toward learning about longer-term investing.</li></ol><p class="explanation">Your combined suggested allocations never exceed your monthly future budget. Employer matching, taxes, local benefits, and individual circumstances may change what makes sense for you. Account balances change only when you update them.</p><div class="modal-actions">${button('Update my situation','financial-profile','primary','arrow')}</div>`);}
function settings(){openModal('Your space, your preferences',`<form data-form="settings">${select('Display currency','currency',{USD:'USD — US dollar',GBP:'GBP — British pound',EUR:'EUR — Euro',CAD:'CAD — Canadian dollar',AUD:'AUD — Australian dollar'},state.settings.currency)}<p class="explanation">Changing currency only changes the label. It does not convert your amounts.</p>${formFooter('Save preferences')}</form><div class="settings-divider"></div><h3>Keep a copy of your plan</h3><p class="explanation">Export a backup to move your plan to another browser. Restoring a backup replaces your current budget after confirmation.</p><div class="setting-buttons" style="margin-top:15px">${button('Export budget backup','export','','download')}<label class="btn">${icon('upload')}Choose a backup to restore<input type="file" id="restore-file" accept=".json,application/json" style="width:160px;font-size:10px" aria-label="Choose budget backup"></label>${button(state.demo?'Start with my own numbers':'Start a fresh budget','start','danger','trash')}</div>`);}
function upload(){importRows=[];openModal('Bring your income with you',`<p>Choose an income CSV, then review it before importing. All rows should use ${state.settings.currency} and take-home amounts.</p><button class="text-btn" data-action="sample">Download an example CSV ↗</button><label class="upload-zone">${icon('upload')}<strong>Choose an income CSV</strong><small>Columns: name, amount, frequency, date (optional)</small><input type="file" id="income-file" accept=".csv,text/csv" aria-label="Choose income CSV"></label><p class="explanation">Frequency values: monthly, weekly, biweekly, semimonthly, yearly, once. Dates use YYYY-MM-DD. Maximum 1 MB. Payslip PDFs and images are not supported in this version.</p><div class="form-error" id="form-error" role="alert"></div><div id="import-preview"></div><div class="modal-actions"><button class="btn" data-action="close">Cancel</button><button class="btn primary" id="import-confirm" data-action="import" disabled>Import income ${icon('arrow')}</button></div>`);}
function download(filename,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
let pendingRestore=null;
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const {action,id,kind}=el.dataset;e.preventDefault();
if(action==='close')closeModal();
else if(action==='navigate'){closeModal();navigate(el.dataset.page);}
else if(action==='add-income'||action==='edit-income')incomeForm(id);
else if(action==='add-bill'||action==='edit-bill')billForm(id);
else if(action==='add-expense')expenseForm();
else if(action==='add-goal'||action==='edit-goal')goalForm(id);
else if(action==='financial-profile'){closeModal();profileForm();}
else if(action==='help')help();
else if(action==='plan-help')planHelp();
else if(action==='settings'){closeModal();settings();}
else if(action==='upload')upload();
else if(action==='scroll-goals')$('#goals')?.scrollIntoView({behavior:'smooth'});
else if(action==='sample')download('penny-income-example.csv',`name,amount,frequency,date\nMy salary,2400,biweekly,${localDate()}\nSide project,300,once,${localDate()}\n`,'text/csv');
else if(action==='export'){download(`penny-budget-${localDate()}.json`,JSON.stringify(state,null,2),'application/json');toast('Your budget backup is ready.');}
else if(action==='start'){closeModal();openModal('A fresh start for your money',`<p>${state.demo?'We’ll clear the example numbers so you can build your own plan.':'This clears the budget saved in this browser. Export a backup first if you want to keep it.'}</p><div class="modal-actions">${button('Keep this budget','close','','close')}${button('Start fresh','confirm-start','primary','arrow')}</div>`);}
else if(action==='confirm-start'){state=emptyState();closeModal();save('A fresh start. Let’s add your income.');incomeForm();}
else if(action==='delete'){const item=state[kind]?.find(r=>r.id===id);if(!item)return;openModal('Remove this item?',`<p>Remove “${esc(item.name)}” from your plan? Your numbers will update immediately.</p><div class="modal-actions">${button('Keep it','close','','close')}${button('Remove item','confirm-delete','danger','trash',`data-kind="${esc(kind)}" data-id="${esc(id)}"`)}</div>`);}
else if(action==='confirm-delete'){if(!['incomes','bills','goals','transactions'].includes(kind))return;state[kind]=state[kind].filter(r=>r.id!==id);closeModal();save('Item removed. Your plan is updated.');}
else if(action==='import'){if(!importRows.length)return;const known=new Set(state.incomes.map(i=>JSON.stringify([i.name,i.amount,i.frequency,i.date])));let added=0;for(const row of importRows){const key=JSON.stringify([row.name,row.amount,row.frequency,row.date]);if(!known.has(key)){state.incomes.push({...row,id:uid()});known.add(key);added++;}}closeModal();save(`${added} income ${added===1?'source':'sources'} added. Exact duplicates were skipped.`);}
else if(action==='confirm-restore'){if(!pendingRestore)return;state=pendingRestore;pendingRestore=null;closeModal();save('Your budget backup is restored.');}
});
document.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const values=Object.fromEntries(new FormData(form));const kind=form.dataset.form;const id=form.dataset.id||uid();let collection,row;
if(values.name!==undefined&&!values.name.trim()){formError('Please enter a name.');return;}
if(['income','bill','expense'].includes(kind)&&(!Number.isFinite(Number(values.amount))||Number(values.amount)<=0)){formError('Please enter an amount greater than zero.');return;}
if(kind==='income'){collection='incomes';row={id,name:values.name.trim(),amount:Number(values.amount),frequency:values.frequency,date:values.date};}
if(kind==='bill'){collection='bills';row={id,name:values.name.trim(),amount:Number(values.amount),category:values.category};}
if(kind==='expense'){collection='transactions';row={id,name:values.name.trim(),amount:Number(values.amount),category:values.category,date:values.date};}
if(kind==='goal'){if(Number(values.target)<=0){formError('Set a goal greater than zero.');return;}collection='goals';row={id,name:values.name.trim(),target:Number(values.target),saved:Number(values.saved)};}
const proposed=structuredClone(state);
if(collection){const index=proposed[collection].findIndex(r=>r.id===id);if(index>=0)proposed[collection][index]=row;else proposed[collection].push(row);}
if(kind==='profile')Object.assign(proposed.settings,{emergencySaved:Number(values.emergencySaved),emergencyMonths:Number(values.emergencyMonths),highInterestDebt:Number(values.highInterestDebt)});
if(kind==='settings')proposed.settings.currency=values.currency;
if(!validateState(proposed)){formError('Please check your amounts and dates. All values must be valid and non-negative.');return;}
state=proposed;closeModal();save(collection==='transactions'?'Purchase logged. Your spending estimate is updated.':'Saved. A little more clarity.');
});
document.addEventListener('input',e=>{if(e.target.id==='future-range')$('#future-display').textContent=e.target.value+'%';if(['activity-search','activity-category'].includes(e.target.id))filterActivity();});
document.addEventListener('change',async e=>{
if(e.target.id==='future-range'){state.settings.futurePercent=Number(e.target.value);save('Your budget balance is updated.');$('#future-range')?.focus({preventScroll:true});}
if(e.target.id==='activity-category')filterActivity();
if(e.target.id==='income-file'){const file=e.target.files[0];if(!file)return;importRows=[];$('#import-confirm').disabled=true;$('#import-preview').innerHTML='';formError('');try{if(file.size>1024*1024)throw new Error('Please choose a CSV smaller than 1 MB.');importRows=parseCSV(await file.text());$('#import-preview').innerHTML=`<div class="import-preview"><h3>${importRows.length} ${importRows.length===1?'source':'sources'} ready to review</h3>${importRows.map(r=>`<div class="stat-line" style="margin-top:12px"><span>${esc(r.name)} · ${FREQUENCIES[r.frequency]}</span><b>${amount(r.amount)}</b></div>`).join('')}</div><p class="explanation">These will be added to your existing sources. Exact duplicates are skipped.</p>`;$('#import-confirm').disabled=false;}catch(error){formError(error.message);}}
if(e.target.id==='restore-file'){const file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw new Error('Please use a backup smaller than 5 MB.');const parsed=JSON.parse(await file.text());if(!validateState(parsed))throw new Error('This file is not a valid Penny budget backup.');pendingRestore=parsed;closeModal();openModal('Restore this budget?',`<p>This backup contains ${parsed.incomes.length} income sources, ${parsed.bills.length} essentials, ${parsed.transactions.length} purchases, and ${parsed.goals.length} goals. It will replace your current budget on this device.</p><div class="modal-actions">${button('Keep my budget','close','','close')}${button('Restore backup','confirm-restore','primary','check')}</div>`);}catch(error){toast(error instanceof SyntaxError?'This is not a valid JSON backup.':error.message);}}
});
function filterActivity(){const query=$('#activity-search').value.toLowerCase();const cat=$('#activity-category').value;const rows=model.transactions.filter(t=>t.name.toLowerCase().includes(query)&&(!cat||t.category===cat));$('#activity-results').innerHTML=rows.length?activityRows(rows,true):empty('No matching purchases','Try another name or category.');}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
render();
